# Carga NAT-261110-01 en el dashboard habitual (Digital Tagging v0.5.1).
# Sustituye el archivo anterior por este y, con la aplicacion detenida, ejecuta:
# source("Cargar_demo_Naturae.R", encoding = "UTF-8")
# Despues inicia el dashboard como siempre y busca Naturae / NAT-261110-01.
# Los valores incluidos son de ejemplo; la procedencia simulada se conserva.
# Este archivo no abre otra aplicacion ni modifica ui.R, server.R o las APIs.

invisible((function() {
  if (!requireNamespace("jsonlite", quietly = TRUE))
    stop("Falta jsonlite. Ejecuta install_packages.R del proyecto.", call. = FALSE)
  sources <- unlist(lapply(sys.frames(), function(frame) {
    x <- tryCatch(frame$ofile, error = function(e) NULL)
    if (is.character(x) && length(x) == 1L && nzchar(x)) x else character()
  }), use.names = FALSE)
  sources <- sources[basename(sources) == "Cargar_demo_Naturae.R"]
  candidates <- unique(c(
    if (length(sources)) dirname(normalizePath(sources, winslash = "/", mustWork = TRUE)) else character(),
    getwd(), Sys.getenv("DIGITAL_TAGGING_PROJECT_DIR", unset = "")))
  valid <- vapply(candidates, function(x) nzchar(x) && all(file.exists(file.path(x,
    c("app.R", "ui.R", "server.R", "R/storage.R", "config/pilots.json")))), logical(1))
  if (!any(valid)) stop("Copia Cargar_demo_Naturae.R junto a app.R y abre el proyecto .Rproj.", call. = FALSE)
  project <- normalizePath(candidates[which(valid)[1L]], winslash = "/", mustWork = TRUE)
  if (!identical(Sys.getenv("DIGITAL_TAGGING_READ_ADAPTER", unset = "local"), "local"))
    stop("El dashboard usa otro origen de lectura. No se han cargado datos locales.", call. = FALSE)
  directory <- Sys.getenv("DIGITAL_TAGGING_DATA_DIR", unset = "")
  if (!nzchar(directory)) directory <- file.path(project, "data", "local")
  else {
    absolute <- startsWith(directory, "/") || startsWith(directory, "~") ||
      grepl("^[A-Za-z]:", directory) || startsWith(directory, "\\\\")
    if (!absolute) directory <- file.path(project, directory)
  }
  directory <- path.expand(directory)
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  if (!dir.exists(directory)) stop("No se pudo crear la carpeta de datos.", call. = FALSE)
  batch_id <- "NAT-261110-01"
  target <- file.path(directory, paste0("NAT__", batch_id, ".json"))
  categories <- c("raw_materials", "production_process", "quality_control", "logistics", "sustainability")
  report <- function(record) {
    counts <- vapply(categories, function(category) length(record[[category]]), integer(1))
    message("Disponible para consulta: Naturae / ", batch_id)
    message(paste(paste(categories, counts, sep = ": "), collapse = " | "))
    message("Abre tu dashboard habitual: Data Visualization > Naturae > ", batch_id, " > Search.")
    invisible(target)
  }
  backup <- NULL
  if (file.exists(target)) {
    existing <- tryCatch(jsonlite::fromJSON(target, simplifyVector = FALSE), error = function(e)
      stop("El archivo existente no se puede leer. Se ha conservado sin modificar.", call. = FALSE))
    if (!identical(existing$metadata$pilot_id, "NAT") ||
        !identical(existing$metadata$batch_id, batch_id))
      stop("El archivo existente no coincide con el piloto y el lote. Se ha conservado.", call. = FALSE)
    if (any(vapply(categories, function(category) length(existing[[category]]) > 0L, logical(1)))) {
      message("El lote ya contiene registros; se conservan sus datos y sus cambios.")
      return(report(existing))
    }
    # Un contexto guardado sin registros se respalda antes de rellenarlo.
    backup_directory <- file.path(directory, "backups")
    dir.create(backup_directory, showWarnings = FALSE)
    backup <- tempfile(pattern = paste0("NAT__", batch_id, "_empty_"),
                       tmpdir = backup_directory, fileext = ".json")
    if (!file.copy(target, backup, overwrite = FALSE))
      stop("No se pudo respaldar el contexto vacio; no se ha modificado.", call. = FALSE)
